def bowling_score(rolls):
    # Validate roll values
    for r in rolls:
        if not isinstance(r, int) or isinstance(r, bool) or r < 0 or r > 10:
            raise ValueError("Invalid roll value")

    n = len(rolls)
    idx = 0
    total = 0

    for frame in range(10):
        if idx >= n:
            raise ValueError("Not enough rolls for a complete game")

        if frame < 9:
            # Frames 1-9
            if rolls[idx] == 10:
                # Strike
                if idx + 2 >= n:
                    raise ValueError("Not enough rolls after a strike")
                total += 10 + rolls[idx + 1] + rolls[idx + 2]
                idx += 1
            else:
                if idx + 1 >= n:
                    raise ValueError("Not enough rolls in frame")
                two = rolls[idx] + rolls[idx + 1]
                if two > 10:
                    raise ValueError("Frame total exceeds 10")
                if two == 10:
                    # Spare
                    if idx + 2 >= n:
                        raise ValueError("Not enough rolls after a spare")
                    total += 10 + rolls[idx + 2]
                else:
                    total += two
                idx += 2
        else:
            # Frame 10 (final frame)
            if rolls[idx] == 10:
                # Strike in final frame, needs two bonus rolls
                if idx + 2 >= n:
                    raise ValueError("Not enough bonus rolls after final strike")
                total += 10 + rolls[idx + 1] + rolls[idx + 2]
                idx += 3
            else:
                if idx + 1 >= n:
                    raise ValueError("Not enough rolls in final frame")
                two = rolls[idx] + rolls[idx + 1]
                if two > 10:
                    raise ValueError("Frame total exceeds 10")
                if two == 10:
                    # Spare in final frame, needs one bonus roll
                    if idx + 2 >= n:
                        raise ValueError("Not enough bonus roll after final spare")
                    total += 10 + rolls[idx + 2]
                    idx += 3
                else:
                    total += two
                    idx += 2

    if idx != n:
        raise ValueError("Too many rolls for a complete game")

    return total
